#define CROW_HIP_ROLL_LIBRARY
#include "../crow-v15-hip-roll-strong-drive-prototype-20261111/probe.cpp"
#include "metalrobo/Collision.hpp"
int main(){auto p=hipRollModel();MRShapeGPU toe{};bool found=false;for(unsigned i=0;i<p.mechanics.shapes.size();i++)if(p.mechanics.shapeNames[i]=="crow_left_front_toe_1_distal/collision"){toe=p.mechanics.shapes[i];found=true;}if(!found)return 1;toe.bodyIndex=0;toe.collisionGroup=toe.collisionMask=~0u;MRShapeGPU perch=toe;perch.bodyIndex=1;perch.dimensions={.025f,.72f,.055f,0};perch.contactRestAndBoundingRadius.z=std::sqrt(.025f*.025f+.72f*.72f+.055f*.055f);std::vector<MRShapeGPU> shapes{toe,perch};std::cout.precision(9);unsigned t;while(std::cin>>t){std::vector<MRBodyStateGPU> b(2);for(auto& x:b){std::cin>>x.position.x>>x.position.y>>x.position.z>>x.orientation.x>>x.orientation.y>>x.orientation.z>>x.orientation.w;x.position.w=1;}b[0].flagsAndIndices[0]=MR_MOTION_DYNAMIC;b[1].flagsAndIndices[0]=MR_MOTION_STATIC;CollisionConfig cfg;cfg.capacities={16,64,16};PersistentManifoldCache cache;auto x=collideCpuReference(shapes,b,cfg,cache);std::cout<<t<<" status "<<int(x.diagnostics.code)<<" pairs "<<x.diagnostics.requiredPairs<<" contacts "<<x.rawContacts.size();for(auto c:x.rawContacts)std::cout<<" separation="<<c.normalAndSeparation.w;std::cout<<"\n";} }
